@php($selectedTags=array_values(array_filter(array_map('trim',explode(',',old('tags',$tagValue))))))
<div class="tag-field fixed-tags dynamic-tags"><label>İşlem etiketleri</label><input type="hidden" name="tags" value="{{implode(', ',$selectedTags)}}"><div class="tag-options">@foreach(array_unique(array_merge($tagOptions,$selectedTags)) as $option)<button type="button" class="tag-option" data-tag="{{$option}}" aria-pressed="{{in_array($option,$selectedTags)?'true':'false'}}">{{$option}}</button>@endforeach</div><div class="new-tag-row"><input class="new-tag-input" aria-label="Yeni işlem etiketi" placeholder="Yeni etiket yazın" maxlength="30"><button class="button-secondary add-tag" type="button">＋ Ekle</button></div><small class="tag-error negative" role="status"></small></div>
